/**
 * Shared progression admission. Authored identities are pinned below independently
 * of catalog ordering, damage tuning and display names. Signed starter payloads
 * remain unchanged. Competitive Tactics opts into its normalized rules explicitly.
 */
export const PET_ABILITY_MILESTONES = [1, 5, 10, 20, 30, 50, 75] as const;
export type PetAbilityRuleset = 'progression' | 'competitive-tactics';
export type PetAbilityTier = 'basic' | 'utility' | 'advanced' | 'signature';
export type PetAbilityUpgrade = 'utility-mastery' | 'offense-mastery' | 'signature-mastery';
export type AuthoredPetAbility = {
    id?: unknown; abilityId?: unknown; baseAbilityId?: unknown; name?: unknown; power?: unknown; kind?: unknown; signature?: unknown;
    cooldown?: unknown; currentCooldown?: unknown; rounds?: unknown;
    element?: unknown; cls?: unknown; target?: unknown; cost?: unknown; priority?: unknown; hold?: unknown; effect?: unknown;
    affinity?: unknown; range?: unknown; aoe?: unknown; synergyElement?: unknown;
};
export type ProgressionPetAbility<T extends AuthoredPetAbility = AuthoredPetAbility> = T & {
    abilityId: string; baseAbilityId: string; unlockLevel: number; tier: PetAbilityTier;
    name: string; kind: string; power: number; signature: boolean;
    upgrade?: PetAbilityUpgrade;
    /** Sparse kits can use a restrained version of an authored finisher. */
    restrained: boolean;
};
export type PetAbilityProgressionInput<T extends AuthoredPetAbility = AuthoredPetAbility> = {
    templateId?: unknown; id?: unknown; evolutionStage?: unknown; rarity?: unknown;
    level?: unknown; role?: unknown; abilities?: readonly T[];
};
/** Admission policy belongs to a trusted caller, never a persisted pet or
 * worker payload. Omitting these controls selects authored progression. */
export type PetAbilityProgressionOptions = Readonly<{
    abilitySource?: 'authored' | 'tactics'; ruleset?: PetAbilityRuleset;
}>;
export type PetAbilityProgression<T extends AuthoredPetAbility = AuthoredPetAbility> = {
    speciesId: string | null; role: string; level: number; ruleset: PetAbilityRuleset;
    abilities: ProgressionPetAbility<T>[]; allAbilities: ProgressionPetAbility<T>[];
    unlocks: { level: number; abilityIds: string[] }[];
    nextUnlock: { level: number; abilityIds: string[] } | null;
};
type SpeciesDefinition = {
    role: string; moves: Record<string, AuthoredPetAbility>;
    slots: string[]; overrideSlots?: string[]; overrideMoves?: Record<string, AuthoredPetAbility>; overrideMarkers?: string[];
};
const ROLES = new Set(['defender', 'tracker', 'assassin', 'sage']);
const UNIVERSAL_ABILITIES = new Set(['universal:tackle', 'universal:guard', 'universal:rest', 'universal:switch']);
const TACTICS_UNLOCKS: Readonly<Record<string, number>> = Object.freeze({
    basic: 1,
    'fire-strike': 1, 'water-strike': 1, 'wind-strike': 1, 'lightning-strike': 1, 'earth-strike': 1,
    'fire-pulse': 10, 'water-pulse': 10, 'wind-pulse': 10, 'lightning-pulse': 10, 'earth-pulse': 10,
    'fire-breaker': 10, 'water-breaker': 10, 'wind-breaker': 10, 'lightning-breaker': 10, 'earth-breaker': 10,
    'fire-sky': 5, 'water-sky': 5, 'wind-sky': 5, 'lightning-sky': 5, 'earth-sky': 5,
    'ember-scar': 10, 'open-wound': 10, undertow: 10,
    expose: 5, bind: 5, mend: 5, aegis: 5, purify: 5, protect: 5, intercept: 5, rally: 5,
});
const wholeLevel = (value: unknown): number => {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.max(1, Math.min(100, Math.floor(parsed))) : 1;
};

/** Resolve owned starter evolution without changing its persistent identity. */
export function petAbilitySpeciesId(input: Pick<PetAbilityProgressionInput, 'templateId' | 'id' | 'evolutionStage' | 'rarity'>): string | null {
    const explicit = typeof input.templateId === 'string' ? input.templateId : '';
    const instance = typeof input.id === 'string' ? input.id : '';
    let speciesId = Object.hasOwn(SPECIES_ABILITIES, explicit) ? explicit
        : Object.hasOwn(SPECIES_ABILITIES, instance) ? instance
        : Object.keys(SPECIES_ABILITIES).sort((a, b) => b.length - a.length)
            .find(id => instance.startsWith(id + '-') || instance.startsWith(id + ':')) ?? null;
    if (!speciesId) return null;
    if (/^starter-(fire|water|wind|lightning|earth)$/.test(speciesId)) {
        const stage = Number(input.evolutionStage) || (input.rarity === 'legendary' ? 2 : input.rarity === 'rare' ? 1 : 0);
        speciesId += stage >= 2 ? '-l' : stage >= 1 ? '-r' : '';
    }
    return speciesId;
}

/** Generic competitive IDs carry their own authored identity; no power sorting. */
export function petTacticsAbilityUnlockLevel(abilityId: string, signature = false): number | null {
    if (Object.hasOwn(TACTICS_UNLOCKS, abilityId)) return TACTICS_UNLOCKS[abilityId];
    if (signature && abilityId.endsWith('-signature')
        && Object.hasOwn(SPECIES_ABILITIES, abilityId.slice(0, -10))) return 20;
    return null;
}

function materialize<T extends AuthoredPetAbility>(
    source: T, baseAbilityId: string, tier: PetAbilityTier, unlockLevel: number,
    upgrade?: PetAbilityUpgrade,
): ProgressionPetAbility<T> {
    // Project the authored combat contract with fixed property names. Arbitrary
    // metadata (including every mastery/upgrade spelling) cannot enter a sealed
    // ability. Preserve optional field presence and every authored/Tactics axis.
    const authored: AuthoredPetAbility = {};
    if (Object.hasOwn(source, 'id')) authored.id = source.id;
    if (Object.hasOwn(source, 'name')) authored.name = source.name;
    if (Object.hasOwn(source, 'power')) authored.power = source.power;
    if (Object.hasOwn(source, 'kind')) authored.kind = source.kind;
    if (Object.hasOwn(source, 'signature')) authored.signature = source.signature;
    if (Object.hasOwn(source, 'cooldown')) authored.cooldown = source.cooldown;
    if (Object.hasOwn(source, 'currentCooldown')) authored.currentCooldown = source.currentCooldown;
    if (Object.hasOwn(source, 'rounds')) authored.rounds = source.rounds;
    if (Object.hasOwn(source, 'element')) authored.element = source.element;
    if (Object.hasOwn(source, 'cls')) authored.cls = source.cls;
    if (Object.hasOwn(source, 'target')) authored.target = source.target;
    if (Object.hasOwn(source, 'cost')) authored.cost = source.cost;
    if (Object.hasOwn(source, 'priority')) authored.priority = source.priority;
    if (Object.hasOwn(source, 'hold')) authored.hold = source.hold;
    if (Object.hasOwn(source, 'effect')) authored.effect = source.effect;
    if (Object.hasOwn(source, 'affinity')) authored.affinity = source.affinity;
    if (Object.hasOwn(source, 'range')) authored.range = source.range;
    if (Object.hasOwn(source, 'aoe')) authored.aoe = source.aoe;
    if (Object.hasOwn(source, 'synergyElement')) authored.synergyElement = source.synergyElement;
    return {
        ...authored,
        abilityId: baseAbilityId + ':' + tier + (upgrade ? ':mastery-' + unlockLevel : ''),
        baseAbilityId, unlockLevel, tier, upgrade,
        name: String(source.name ?? 'Companion Art'), kind: String(source.kind ?? 'damage'),
        power: Number.isFinite(Number(source.power)) ? Math.max(0, Number(source.power)) : 0,
        signature: tier === 'signature',
        restrained: tier === 'basic',
    } as ProgressionPetAbility<T>;
}

function withMastery<T extends AuthoredPetAbility>(base: ProgressionPetAbility<T>): ProgressionPetAbility<T>[] {
    const mastery = base.tier === 'utility' ? { level: 30, upgrade: 'utility-mastery' as const }
        : base.tier === 'advanced' ? { level: 50, upgrade: 'offense-mastery' as const }
        : base.tier === 'signature' ? { level: 75, upgrade: 'signature-mastery' as const } : null;
    return mastery ? [base, materialize(base, base.baseAbilityId, base.tier, mastery.level, mastery.upgrade)] : [base];
}

function speciesAbilities<T extends AuthoredPetAbility>(input: PetAbilityProgressionInput<T>, speciesId: string | null): ProgressionPetAbility<T>[] {
    if (!speciesId) return legacyAbilities(input.abilities ?? []);
    const definition = SPECIES_ABILITIES[speciesId];
    const supplied = input.abilities ?? [];
    const byName = new Map(supplied.map(move => [String(move.name), move]));
    const byId = new Map(supplied.flatMap(move => [move.id, move.abilityId, move.baseAbilityId]
        .filter((id): id is string => typeof id === 'string').map(id => [id, move] as const)));
    // An override profile is selected only by its explicit authored identities.
    // Missing support in an override retains the species' canonical utility.
    const override = definition.overrideSlots;
    const useOverride = override && definition.overrideMarkers?.some(name => byName.has(name)
        || Object.entries(definition.overrideMoves ?? {}).some(([id, move]) => move.name === name && byId.has(id)));
    const slots = useOverride ? override : definition.slots;
    const tiers: readonly PetAbilityTier[] = ['basic', 'utility', 'advanced', 'signature'];
    const levels = [1, 5, 10, 20];
    return slots.flatMap((id, i) => {
        const canonical = useOverride ? definition.overrideMoves?.[id] ?? definition.moves[id] : definition.moves[id];
        const source = (byId.get(id) ?? byName.get(String(canonical.name)) ?? canonical) as T;
        return withMastery(materialize(source, id, tiers[i], levels[i]));
    });
}

/** Unknown legacy/custom species keep a conservative sealed fallback. These
 * compatibility slot identities are never used for a catalog species. */
function legacyAbilities<T extends AuthoredPetAbility>(supplied: readonly T[]): ProgressionPetAbility<T>[] {
    const moves = [...supplied].sort((a, b) => String(a.name).localeCompare(String(b.name)));
    const signature = moves.find(move => move.signature === true);
    const supportKinds = new Set(['heal', 'shield', 'barrier', 'absorb', 'buff', 'debuff', 'mark', 'slow', 'haste', 'taunt', 'cleanse', 'protect', 'weather']);
    const offensiveKinds = new Set(['damage', 'burn', 'dot', 'wound', 'lifesteal', 'crush', 'stun', 'freeze', 'confuse', 'debuff', 'mark', 'slow', 'movelock', 'push', 'pull', 'pivot']);
    const support = moves.find(move => !move.signature && supportKinds.has(String(move.kind)));
    const offense = moves.filter(move => !move.signature && Number(move.power) > 0
        && offensiveKinds.has(String(move.kind)));
    const basic = offense[0] ?? (signature && Number(signature.power) > 0 && offensiveKinds.has(String(signature.kind)) ? signature : undefined);
    const advanced = offense[1] ?? basic;
    return [
        ...(basic ? withMastery(materialize(basic, 'legacy:basic', 'basic', 1)) : []),
        ...(support ? withMastery(materialize(support, 'legacy:utility', 'utility', 5)) : []),
        ...(advanced ? withMastery(materialize(advanced, 'legacy:advanced', 'advanced', 10)) : []),
        ...(signature ? withMastery(materialize(signature, 'legacy:signature', 'signature', 20)) : []),
    ];
}

/** The caller supplies the canonical competitive species pool when translating a
 * saved competitive loadout into progression. Saved choices themselves stay intact. */
function tacticsAbilities<T extends AuthoredPetAbility>(input: PetAbilityProgressionInput<T>, speciesId: string | null): ProgressionPetAbility<T>[] {
    return (input.abilities ?? []).flatMap(source => {
        const id = typeof source.id === 'string' ? source.id : '';
        const signature = id === speciesId + '-signature' && source.signature !== false;
        const level = petTacticsAbilityUnlockLevel(id, signature);
        if (level == null) return [];
        const tier: PetAbilityTier = signature ? 'signature' : level === 1 ? 'basic' : level === 10 ? 'advanced' : 'utility';
        return withMastery(materialize(source, id, tier, level));
    });
}

export function resolvePetAbilityProgression<T extends AuthoredPetAbility>(
    input: PetAbilityProgressionInput<T>, options: PetAbilityProgressionOptions = {},
): PetAbilityProgression<T> {
    const speciesId = petAbilitySpeciesId(input);
    const level = wholeLevel(input.level);
    const ruleset = options.ruleset ?? 'progression';
    const role = speciesId ? SPECIES_ABILITIES[speciesId].role
        : ROLES.has(String(input.role)) ? String(input.role) : 'defender';
    const allAbilities = options.abilitySource === 'tactics'
        ? tacticsAbilities(input, speciesId) : speciesAbilities(input, speciesId);
    if (ruleset === 'competitive-tactics') {
        const abilities = allAbilities.filter(move => !move.upgrade).map(move => ({ ...move, unlockLevel: 1, restrained: false }));
        return { speciesId, role, level, ruleset, abilities, allAbilities: abilities, unlocks: [], nextUnlock: null };
    }
    const eligible = allAbilities.filter(move => level >= move.unlockLevel);
    const current = new Map<string, ProgressionPetAbility<T>>();
    for (const move of eligible) current.set(move.baseAbilityId + ':' + move.tier, move);
    const unlocks = PET_ABILITY_MILESTONES.map(milestone => ({
        level: milestone, abilityIds: allAbilities.filter(move => move.unlockLevel === milestone).map(move => move.abilityId),
    })).filter(unlock => unlock.abilityIds.length > 0);
    return {
        speciesId, role, level, ruleset, allAbilities, abilities: [...current.values()],
        unlocks, nextUnlock: unlocks.find(unlock => unlock.level > level) ?? null,
    };
}

/** Learned eligibility is separate from which upgraded variant is currently
 * equipped. Commands must additionally match the immutable sealed move list. */
export function petAbilityEligibility<T extends AuthoredPetAbility>(input: PetAbilityProgressionInput<T>, abilityId: string, options: PetAbilityProgressionOptions = {}): {
    eligible: boolean; requiredLevel: number | null; reason: 'unlocked' | 'level-locked' | 'unknown-ability';
} {
    if (UNIVERSAL_ABILITIES.has(abilityId)) return { eligible: true, requiredLevel: 1, reason: 'unlocked' };
    const resolved = resolvePetAbilityProgression(input, options);
    const match = resolved.allAbilities.find(move => move.abilityId === abilityId)
        ?? resolved.allAbilities.find(move => move.baseAbilityId === abilityId);
    if (!match) return { eligible: false, requiredLevel: null, reason: 'unknown-ability' };
    const eligible = resolved.ruleset === 'competitive-tactics' || resolved.level >= match.unlockLevel;
    return { eligible, requiredLevel: match.unlockLevel, reason: eligible ? 'unlocked' : 'level-locked' };
}


